#include <iostream>
#include <verilated.h>
#include "Vtb_zfp_top.h" // Generated by Verilator

vluint64_t main_time = 0; // Simulation time tracker

// Called by $time in Verilog
double sc_time_stamp() {
    return main_time;
}

void toggle_clock(Vtb_zfp_top* top) {
    top->clk = !top->clk;
    top->eval();
    main_time += 5;
    top->clk = !top->clk;
    top->eval();
    main_time += 5;
}

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Vtb_zfp_top* top = new Vtb_zfp_top;

    // 1. Initialize Inputs
    top->clk = 0;
    top->rst = 1;
    top->s_tx_tvalid = 0;
    top->s_tx_tlast = 0;
    top->m_rx_tready = 0xFF; // Decompressor is ready to receive

    // 2. Reset Sequence
    std::cout << "Applying Reset..." << std::endl;
    for (int i = 0; i < 5; i++) toggle_clock(top);
    top->rst = 0;
    for (int i = 0; i < 5; i++) toggle_clock(top);

    // 3. Drive AXI Stream Data (Stimulus)
    std::cout << "Injecting Data..." << std::endl;
    
    // Write cycle 1
    top->s_tx_tvalid = 1;
    // Set mock data (e.g. setting some header bits and comp modes)
    // Note: Vtb_zfp_top uses WData arrays for wide signals > 64 bits
    top->s_tx_tdata[0] = 0xDEADBEEF; // lower 32 bits
    top->s_tx_tdata[3] = 0x00000001; // COMP_MODE_ORIGIN data injection
    top->s_tx_tkeep = 0xFF; // Valid bytes
    top->s_tx_tlast = 0;

    toggle_clock(top);

    // Write cycle 2 (Last)
    if (top->s_tx_tready) {
        top->s_tx_tdata[0] = 0xCAFEBABE;
        top->s_tx_tlast = 1;
        toggle_clock(top);
        
        // Clear inputs
        top->s_tx_tvalid = 0;
        top->s_tx_tlast = 0;
    }

    // 4. Monitor outputs for a few cycles
    std::cout << "Monitoring Outputs..." << std::endl;
    for (int i = 0; i < 20; i++) {
        toggle_clock(top);
        if (top->m_rx_tvalid != 0) {
            std::cout << "Time: " << main_time 
                      << " | RX Data valid! RX_TVALID: " << (int)top->m_rx_tvalid 
                      << std::endl;
        }
    }

    top->final();
    delete top;
    return 0;
}